exempt = (input('exempt_assets') || {})['CKV_AWS_16'] || []

control 'CKV_AWS_16' do
  title 'Ensure all data stored in the RDS is securely encrypted at rest'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_db_instance resources that actually exist, read through the
    stock inspec-aws aws_rds_instance resource.
  DESC

  desc 'rationale', <<~RATIONALE
    An unencrypted database exposes its data through any snapshot copy or
    storage-layer access, without touching the database itself.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_db_instance: storage_encrypted is True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_db_instance:

      resource "aws_db_instance" "example" {
        storage_encrypted = true
        kms_key_id        = aws_kms_key.rds.arn
      }

    Out of band — aws_db_instance:

      Encryption cannot be enabled in place: snapshot, copy the snapshot with --kms-key-id, and restore.
  FIX

  tag checkov_id:            'CKV_AWS_16'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_db_instance]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/db_instance#storage-encrypted'
  tag nist:                  ['SC-28', 'SC-28 (1)']
  tag nist_r4:               ['SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-001199', 'CCI-002475']
  tag ksi:                   ['KSI-SVC-CER']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
  # resource is an ARGUMENT to `describe`, which evaluates on the control --
  # calling it inside the block would defer it into the example.
  ids = aws_rds_instances.db_instance_identifiers
  in_scope = ids.reject { |id| checkov_exempt?(id: id, type: 'aws_db_instance', rules: exempt) }

  applicable = !in_scope.empty?
  impact 0.7
  impact 0.0 unless applicable
  only_if('no aws_db_instance in scope') { applicable }

  in_scope.each do |id|
    describe aws_rds_instance(id) do
      its('storage_encrypted') { should eq true }
    end
  end
end
